import { S3Client, PutObjectCommand, DeleteBucketCommand } from "@aws-sdk/client-s3";
import { checkpoint, restore } from "@tigrisdata/agent-kit";
import fs from "fs";

const BUCKET_NAME = "pipeline-state";
const endpoint = "https://t3.storage.dev";
const region = "auto";

const s3Client = new S3Client({
  endpoint,
  region,
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});

async function main() {
  // 1. Upload v1
  console.log("Uploading v1.txt (version=1)...");
  await s3Client.send(new PutObjectCommand({
    Bucket: BUCKET_NAME,
    Key: "v1.txt",
    Body: "version=1",
  }));

  // 2. Checkpoint
  console.log("Taking checkpoint...");
  const { data: ckpt, error: ckptError } = await checkpoint(BUCKET_NAME, { name: "before-mutation" });
  if (ckptError) {
    console.error("Checkpoint error:", ckptError);
    process.exit(1);
  }
  if (!ckpt) {
      console.error("Checkpoint data is null");
      process.exit(1);
  }
  const snapshotId = ckpt.snapshotId;
  console.log(`Checkpoint taken: ${snapshotId}`);

  // 3. Mutate
  console.log("Mutating v1.txt (version=2)...");
  await s3Client.send(new PutObjectCommand({
    Bucket: BUCKET_NAME,
    Key: "v1.txt",
    Body: "version=2",
  }));

  // 4. Restore
  console.log("Restoring checkpoint...");
  const { data: restored, error: restoreError } = await restore(BUCKET_NAME, snapshotId, { forkName: "rollback-recovery" });
  if (restoreError) {
    console.error("Restore error:", restoreError);
    process.exit(1);
  }
  if (!restored) {
      console.error("Restored data is null");
      process.exit(1);
  }
  const recoveryBucket = restored.bucket;
  console.log(`Restored to bucket: ${recoveryBucket}`);

  // Write recovery.json
  const recoveryJsonPath = "/home/user/chained-ckpt/recovery.json";
  fs.writeFileSync(recoveryJsonPath, JSON.stringify({ recoveryBucket }));
  console.log(`Wrote ${recoveryJsonPath}`);

  // 5. Tear down the recovery fork
  console.log(`Deleting recovery bucket: ${recoveryBucket}...`);
  try {
    await s3Client.send(new DeleteBucketCommand({
      Bucket: recoveryBucket,
    }));
    console.log("Recovery bucket deleted.");
  } catch (err) {
    console.error("Error deleting bucket with S3 client, trying shell command...", err);
    // Fallback to shell command as suggested in implementation guide
    const { execSync } = await import("child_process");
    execSync(`tigris buckets delete ${recoveryBucket}`);
    console.log("Recovery bucket deleted via CLI.");
  }
}

main().catch((err) => {
  console.error("Main error:", err);
  process.exit(1);
});

import { S3Client, ListBucketsCommand } from "@aws-sdk/client-s3";

const endpoint = "https://t3.storage.dev";
const region = "auto";

const s3Client = new S3Client({
  endpoint,
  region,
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});

async function main() {
  const data = await s3Client.send(new ListBucketsCommand({}));
  console.log("Buckets:", data.Buckets?.map(b => b.Name));
}

main().catch(console.error);

